     1→import { z } from 'zod';
     2→import { QueueItemSchema, IdeaSchema, ClaimIdeaResponseSchema, type QueueItem, type Idea, type IdeaStatus, type ClaimIdeaResponse } from '@utmessa/shared';
     3→import {
     4→  IntakeNetworkError,
     5→  IntakeAuthError,
     6→  IntakeAPIError,
     7→  IntakeValidationError,
     8→  IdeaAlreadyClaimedError,
     9→  IdeaNotFoundError,
    10→  IntakeUnavailableError,
    11→} from '../errors/index.js';
    12→import { createLogger } from '../utils/index.js';
    13→import type { IntakeClientConfig, IIntakeClient } from '../types/index.js';
    14→
    15→const logger = createLogger('IntakeClient');
    16→
    17→/**
    18→ * HTTP client for communicating with the Intake API
    19→ *
    20→ * Handles:
    21→ * - Authentication via X-ORCH-KEY header
    22→ * - Request timeout
    23→ * - Response validation with partial recovery
    24→ * - Error classification (network, auth, API, validation)
    25→ */
    26→export class IntakeClient implements IIntakeClient {
    27→  private readonly baseUrl: string;
    28→  private readonly apiKey: string;
    29→  private readonly timeout: number;
    30→
    31→  constructor(config: IntakeClientConfig) {
    32→    this.baseUrl = config.baseUrl.replace(/\/$/, ''); // Remove trailing slash
    33→    this.apiKey = config.apiKey;
    34→    this.timeout = config.timeout;
    35→  }
    36→
    37→  /**
    38→   * Fetch ideas from Intake API filtered by statuses
    39→   *
    40→   * @param statuses - Array of statuses to filter by
    41→   * @returns Promise resolving to array of valid queue items (QueueItem, not full Idea)
    42→   * @throws IntakeNetworkError on network failure
    43→   * @throws IntakeAuthError on 401/403
    44→   * @throws IntakeAPIError on other HTTP errors
    45→   * @throws IntakeValidationError on invalid response schema
    46→   */
    47→  async fetchIdeas(statuses: IdeaStatus[]): Promise<QueueItem[]> {
    48→    const statusParam = statuses.join(',');
    49→    const url = `${this.baseUrl}/api/ideas?status=${encodeURIComponent(statusParam)}`;
    50→
    51→    logger.debug({ url, statuses }, 'Fetching ideas from Intake API');
    52→
    53→    try {
    54→      const response = await fetch(url, {
    55→        method: 'GET',
    56→        headers: {
    57→          'X-ORCH-KEY': this.apiKey,
    58→          Accept: 'application/json',
    59→        },
    60→        signal: AbortSignal.timeout(this.timeout),
    61→      });
    62→
    63→      // Handle HTTP errors
    64→      if (!response.ok) {
    65→        const body = await this.safeParseBody(response);
    66→
    67→        if (response.status === 401 || response.status === 403) {
    68→          logger.warn(
    69→            { status: response.status },
    70→            'Authentication failed with Intake API'
    71→          );
    72→          throw new IntakeAuthError(
    73→            `Authentication failed: ${response.statusText}`,
    74→            response.status as 401 | 403
    75→          );
    76→        }
    77→
    78→        logger.error(
    79→          { status: response.status, body },
    80→          'Intake API returned error'
    81→        );
    82→        throw new IntakeAPIError(
    83→          `Intake API error: ${response.status} ${response.statusText}`,
    84→          response.status,
    85→          body
    86→        );
    87→      }
    88→
    89→      // Parse successful response
    90→      const json: unknown = await response.json();
    91→      logger.debug({ responseType: typeof json }, 'Received response from Intake API');
    92→
    93→      // Validate and return queue items
    94→      const queueItems = this.validateQueueItems(json);
    95→      logger.info({ count: queueItems.length }, 'Successfully fetched queue items');
    96→
    97→      return queueItems;
    98→    } catch (error) {
    99→      // Re-throw our custom errors
   100→      if (
   101→        error instanceof IntakeNetworkError ||
   102→        error instanceof IntakeAuthError ||
   103→        error instanceof IntakeAPIError ||
   104→        error instanceof IntakeValidationError
   105→      ) {
   106→        throw error;
   107→      }
   108→
   109→      // Convert fetch errors to IntakeNetworkError
   110→      if (error instanceof Error) {
   111→        if (error.name === 'TimeoutError' || error.name === 'AbortError') {
   112→          logger.warn({ timeout: this.timeout }, 'Request timed out');
   113→          throw new IntakeNetworkError(
   114→            `Request timed out after ${this.timeout}ms`,
   115→            error
   116→          );
   117→        }
   118→
   119→        logger.error({ error: error.message }, 'Network error during fetch');
   120→        throw new IntakeNetworkError(`Network error: ${error.message}`, error);
   121→      }
   122→
   123→      // Unknown error type
   124→      throw new IntakeNetworkError('Unknown network error');
   125→    }
   126→  }
   127→
   128→  /**
   129→   * Safely parse response body as JSON
   130→   */
   131→  private async safeParseBody(response: Response): Promise<unknown> {
   132→    try {
   133→      return await response.json();
   134→    } catch {
   135→      return undefined;
   136→    }
   137→  }
   138→
   139→  /**
   140→   * Validate queue items array with partial recovery
   141→   *
   142→   * If the full array validation fails, attempts to validate each item
   143→   * individually and returns valid items. Only throws if no valid items found.
   144→   * 
   145→   * Note: Intake API returns QueueItem[] (not full Idea[]) which excludes
   146→   * sensitive fields like token and email.
   147→   */
   148→  private validateQueueItems(data: unknown): QueueItem[] {
   149→    // First, ensure we have an array-like response
   150→    if (!this.isIdeasResponse(data)) {
   151→      logger.error(
   152→        { responseType: typeof data },
   153→        'Response is not in expected format'
   154→      );
   155→      throw new IntakeValidationError('Response is not in expected format', [
   156→        { path: 'root', message: 'Expected object with ideas array' },
   157→      ]);
   158→    }
   159→
   160→    const items = data.ideas;
   161→
   162→    // Handle empty array (no ideas in queue)
   163→    if (items.length === 0) {
   164→      logger.debug('Empty queue response (no ideas)');
   165→      return [];
   166→    }
   167→
   168→    // Fast path: try validating the whole array
   169→    const arraySchema = z.array(QueueItemSchema);
   170→    const fullResult = arraySchema.safeParse(items);
   171→
   172→    if (fullResult.success) {
   173→      return fullResult.data;
   174→    }
   175→
   176→    // Slow path: validate each item individually for partial recovery
   177→    logger.warn(
   178→      { errorCount: fullResult.error.errors.length },
   179→      'Full validation failed, attempting partial recovery'
   180→    );
   181→
   182→    const validItems: QueueItem[] = [];
   183→    const validationErrors: Array<{ path: string; message: string }> = [];
   184→
   185→    for (let i = 0; i < items.length; i++) {
   186→      const item = items[i];
   187→      const result = QueueItemSchema.safeParse(item);
   188→
   189→      if (result.success) {
   190→        validItems.push(result.data);
   191→      } else {
   192→        const errors = result.error.errors.map((e) => ({
   193→          path: `ideas[${i}].${e.path.join('.')}`,
   194→          message: e.message,
   195→        }));
   196→        validationErrors.push(...errors);
   197→        logger.warn(
   198→          { index: i, errors: errors.map((e) => e.message) },
   199→          'Skipping invalid queue item'
   200→        );
   201→      }
   202→    }
   203→
   204→    // If we recovered some valid items, return them
   205→    if (validItems.length > 0) {
   206→      logger.info(
   207→        { validCount: validItems.length, invalidCount: items.length - validItems.length },
   208→        'Partial recovery successful'
   209→      );
   210→      return validItems;
   211→    }
   212→
   213→    // No valid items - this is not an error, just means nothing matches the queue filter
   214→    // (e.g., all ideas are claimed, running, etc.)
   215→    logger.info(
   216→      { totalItems: items.length, filteredOut: items.length },
   217→      'No ideas match queue filter (all filtered out)'
   218→    );
   219→    return [];
   220→  }
   221→
   222→  /**
   223→   * Type guard for the expected response format
   224→   */
   225→  private isIdeasResponse(
   226→    data: unknown
   227→  ): data is { ideas: unknown[]; total: number } {
   228→    return (
   229→      typeof data === 'object' &&
   230→      data !== null &&
   231→      'ideas' in data &&
   232→      Array.isArray((data as Record<string, unknown>).ideas)
   233→    );
   234→  }
   235→
   236→  /**
   237→   * Claim an idea from Intake API for processing
   238→   *
   239→   * @param ideaId - UUID of the idea to claim
   240→   * @param claimedBy - Identifier of the claiming orchestrator (e.g., hostname)
   241→   * @returns The claimed idea with all fields including token
   242→   * @throws IdeaAlreadyClaimedError if idea is already claimed (409)
   243→   * @throws IdeaNotFoundError if idea doesn't exist (404)
   244→   * @throws IntakeUnavailableError on network/server errors
   245→   * @throws IntakeAuthError on authentication failure (401/403)
   246→   */
   247→  async claimIdea(ideaId: string, claimedBy: string): Promise<ClaimIdeaResponse> {
   248→    const url = `${this.baseUrl}/api/ideas/${encodeURIComponent(ideaId)}/claim`;
   249→
   250→    logger.debug({ ideaId, claimedBy }, 'Claiming idea from Intake API');
   251→
   252→    try {
   253→      const response = await fetch(url, {
   254→        method: 'POST',
   255→        headers: {
   256→          'X-ORCH-KEY': this.apiKey,
   257→          'Content-Type': 'application/json',
   258→          Accept: 'application/json',
   259→        },
   260→        body: JSON.stringify({ claimedBy }),
   261→        signal: AbortSignal.timeout(this.timeout),
   262→      });
   263→
   264→      // Handle HTTP errors
   265→      if (!response.ok) {
   266→        await this.handleClaimError(response, ideaId);
   267→      }
   268→
   269→      // Parse successful response
   270→      const json: unknown = await response.json();
   271→      logger.debug({ ideaId }, 'Received claim response from Intake API');
   272→
   273→      // Validate response
   274→      const result = ClaimIdeaResponseSchema.safeParse(json);
   275→      if (!result.success) {
   276→        logger.error(
   277→          { ideaId, errors: result.error.errors },
   278→          'Invalid claim response schema'
   279→        );
   280→        throw new IntakeValidationError(
   281→          'Invalid claim response from Intake API',
   282→          result.error.errors.map((e) => ({
   283→            path: e.path.join('.'),
   284→            message: e.message,
   285→          }))
   286→        );
   287→      }
   288→
   289→      // Log success with masked token
   290→      logger.info(
   291→        { ideaId, token: `${result.data.token.slice(0, 4)}...` },
   292→        'Successfully claimed idea'
   293→      );
   294→
   295→      return result.data;
   296→    } catch (error) {
   297→      // Re-throw our custom errors
   298→      if (
   299→        error instanceof IdeaAlreadyClaimedError ||
   300→        error instanceof IdeaNotFoundError ||
   301→        error instanceof IntakeUnavailableError ||
   302→        error instanceof IntakeNetworkError ||
   303→        error instanceof IntakeAuthError ||
   304→        error instanceof IntakeAPIError ||
   305→        error instanceof IntakeValidationError
   306→      ) {
   307→        throw error;
   308→      }
   309→
   310→      // Convert fetch errors to IntakeUnavailableError
   311→      if (error instanceof Error) {
   312→        if (error.name === 'TimeoutError' || error.name === 'AbortError') {
   313→          logger.warn({ ideaId, timeout: this.timeout }, 'Claim request timed out');
   314→          throw new IntakeUnavailableError(
   315→            `Request timed out after ${this.timeout}ms`,
   316→            error
   317→          );
   318→        }
   319→
   320→        logger.error({ ideaId, error: error.message }, 'Network error during claim');
   321→        throw new IntakeUnavailableError(`Network error: ${error.message}`, error);
   322→      }
   323→
   324→      // Unknown error type
   325→      throw new IntakeUnavailableError('Unknown network error');
   326→    }
   327→  }
   328→
   329→  /**
   330→   * Delete an idea from Intake API
   331→   *
   332→   * @param ideaId - UUID of the idea to delete
   333→   * @returns True if idea was deleted
   334→   * @throws IdeaNotFoundError if idea doesn't exist (404)
   335→   * @throws IntakeUnavailableError on network/server errors
   336→   * @throws IntakeAuthError on authentication failure (401/403)
   337→   */
   338→  async deleteIdea(ideaId: string): Promise<boolean> {
   339→    const url = `${this.baseUrl}/api/ideas/${encodeURIComponent(ideaId)}`;
   340→
   341→    logger.debug({ ideaId }, 'Deleting idea from Intake API');
   342→
   343→    try {
   344→      const response = await fetch(url, {
   345→        method: 'DELETE',
   346→        headers: {
   347→          'X-ORCH-KEY': this.apiKey,
   348→          Accept: 'application/json',
   349→        },
   350→        signal: AbortSignal.timeout(this.timeout),
   351→      });
   352→
   353→      // Handle HTTP errors
   354→      if (!response.ok) {
   355→        await this.handleDeleteError(response, ideaId);
   356→      }
   357→
   358→      // Parse successful response
   359→      const json = await response.json() as { success: boolean; deleted: boolean; id: string };
   360→      logger.info({ ideaId }, 'Successfully deleted idea');
   361→
   362→      return json.deleted;
   363→    } catch (error) {
   364→      // Re-throw our custom errors
   365→      if (
   366→        error instanceof IdeaNotFoundError ||
   367→        error instanceof IntakeUnavailableError ||
   368→        error instanceof IntakeNetworkError ||
   369→        error instanceof IntakeAuthError ||
   370→        error instanceof IntakeAPIError
   371→      ) {
   372→        throw error;
   373→      }
   374→
   375→      // Convert fetch errors to IntakeUnavailableError
   376→      if (error instanceof Error) {
   377→        if (error.name === 'TimeoutError' || error.name === 'AbortError') {
   378→          logger.warn({ ideaId, timeout: this.timeout }, 'Delete request timed out');
   379→          throw new IntakeUnavailableError(
   380→            `Request timed out after ${this.timeout}ms`,
   381→            error
   382→          );
   383→        }
   384→
   385→        logger.error({ ideaId, error: error.message }, 'Network error during delete');
   386→        throw new IntakeUnavailableError(`Network error: ${error.message}`, error);
   387→      }
   388→
   389→      // Unknown error type
   390→      throw new IntakeUnavailableError('Unknown network error');
   391→    }
   392→  }
   393→
   394→  /**
   395→   * Handle error responses from delete endpoint
   396→   */
   397→  private async handleDeleteError(response: Response, ideaId: string): Promise<never> {
   398→    const body = await this.safeParseBody(response);
   399→
   400→    switch (response.status) {
   401→      case 401:
   402→      case 403:
   403→        logger.warn(
   404→          { status: response.status, ideaId },
   405→          'Authentication failed for delete request'
   406→        );
   407→        throw new IntakeAuthError(
   408→          `Authentication failed: ${response.statusText}`,
   409→          response.status as 401 | 403
   410→        );
   411→
   412→      case 404:
   413→        logger.warn({ ideaId }, 'Idea not found for deletion');
   414→        throw new IdeaNotFoundError(ideaId);
   415→
   416→      default:
   417→        if (response.status >= 500) {
   418→          logger.error(
   419→            { status: response.status, ideaId, body },
   420→            'Intake API server error during delete'
   421→          );
   422→          throw new IntakeUnavailableError(
   423→            `Server error: ${response.status} ${response.statusText}`
   424→          );
   425→        }
   426→
   427→        logger.error(
   428→          { status: response.status, ideaId, body },
   429→          'Intake API returned unexpected error during delete'
   430→        );
   431→        throw new IntakeAPIError(
   432→          `Intake API error: ${response.status} ${response.statusText}`,
   433→          response.status,
   434→          body
   435→        );
   436→    }
   437→  }
   438→
   439→  /**
   440→   * Handle error responses from claim endpoint
   441→   */
   442→  private async handleClaimError(response: Response, ideaId: string): Promise<never> {
   443→    const body = await this.safeParseBody(response);
   444→
   445→    switch (response.status) {
   446→      case 401:
   447→      case 403:
   448→        logger.warn(
   449→          { status: response.status, ideaId },
   450→          'Authentication failed for claim request'
   451→        );
   452→        throw new IntakeAuthError(
   453→          `Authentication failed: ${response.statusText}`,
   454→          response.status as 401 | 403
   455→        );
   456→
   457→      case 404:
   458→        logger.warn({ ideaId }, 'Idea not found');
   459→        throw new IdeaNotFoundError(ideaId);
   460→
   461→      case 409:
   462→        logger.warn({ ideaId }, 'Idea already claimed');
   463→        throw new IdeaAlreadyClaimedError(ideaId);
   464→
   465→      default:
   466→        if (response.status >= 500) {
   467→          logger.error(
   468→            { status: response.status, ideaId, body },
   469→            'Intake API server error during claim'
   470→          );
   471→          throw new IntakeUnavailableError(
   472→            `Server error: ${response.status} ${response.statusText}`
   473→          );
   474→        }
   475→
   476→        logger.error(
   477→          { status: response.status, ideaId, body },
   478→          'Intake API returned unexpected error during claim'
   479→        );
   480→        throw new IntakeAPIError(
   481→          `Intake API error: ${response.status} ${response.statusText}`,
   482→          response.status,
   483→          body
   484→        );
   485→    }
   486→  }
   487→}
