     1→import { NextRequest, NextResponse } from 'next/server';
     2→import { SubmitIdeaRequestSchema } from '@utmessa/shared';
     3→import type { SubmitIdeaRequest, SubmitIdeaResponse, QueueItem } from '@utmessa/shared';
     4→import { createIdea } from '@/lib/db/ideas';
     5→import { generateToken } from '@/lib/utils/tokens';
     6→import { IDEA_STATUS } from '@/lib/db/types';
     7→import { validateOrchKey } from '@/lib/auth/validateOrchKey';
     8→import {
     9→  validateListIdeasParams,
    10→  ValidationError,
    11→} from '@/lib/validators/listIdeasParams';
    12→import { listIdeas } from '@/lib/services/ideasService';
    13→
    14→/**
    15→ * Response type for GET /api/ideas endpoint
    16→ * Returns QueueItem array (excludes sensitive fields like email, token)
    17→ */
    18→interface ListIdeasApiResponse {
    19→  ideas: QueueItem[];
    20→  total: number;
    21→}
    22→
    23→/**
    24→ * POST /api/ideas
    25→ *
    26→ * Submit a new POC idea. This is a public endpoint.
    27→ *
    28→ * Request body should match SubmitIdeaRequestSchema:
    29→ * - title: string (required, 1-100 chars)
    30→ * - problem: string (required, 10-500 chars)
    31→ * - mustHaves: string[] (optional, 1-10 items, each max 100 chars)
    32→ * - email: string (optional, valid email format)
    33→ *
    34→ * Response:
    35→ * - 201 Created: { id, token, createdAt }
    36→ * - 400 Bad Request: { error, details }
    37→ * - 500 Internal Server Error: { error }
    38→ */
    39→export async function POST(request: NextRequest) {
    40→  try {
    41→    // Parse request body
    42→    let body: unknown;
    43→    try {
    44→      body = await request.json();
    45→    } catch {
    46→      return NextResponse.json(
    47→        {
    48→          error: 'Invalid JSON',
    49→          details: [{ field: 'body', message: 'Request body must be valid JSON' }],
    50→        },
    51→        { status: 400 }
    52→      );
    53→    }
    54→
    55→    // Validate with Zod schema from @utmessa/shared
    56→    const validationResult = SubmitIdeaRequestSchema.safeParse(body);
    57→    if (!validationResult.success) {
    58→      return NextResponse.json(
    59→        {
    60→          error: 'Validation failed',
    61→          details: validationResult.error.errors.map((err) => ({
    62→            field: err.path.join('.'),
    63→            message: err.message,
    64→          })),
    65→        },
    66→        { status: 400 }
    67→      );
    68→    }
    69→
    70→    const data: SubmitIdeaRequest = validationResult.data;
    71→
    72→    // Generate unique receipt token
    73→    const token = generateToken();
    74→
    75→    // Save to database
    76→    const idea = await createIdea({
    77→      token,
    78→      title: data.title,
    79→      problem: data.problem,
    80→      mustHaves: data.mustHaves || [],
    81→      email: data.email || null,
    82→      status: IDEA_STATUS.SUBMITTED,
    83→    });
    84→
    85→    // Format response
    86→    const response: SubmitIdeaResponse = {
    87→      id: idea.id,
    88→      token: idea.token,
    89→      createdAt: idea.createdAt.toISOString(),
    90→    };
    91→
    92→    return NextResponse.json(response, { status: 201 });
    93→  } catch (error) {
    94→    // Log error for debugging
    95→    console.error('Error creating idea:', error);
    96→
    97→    // Return generic error to client
    98→    return NextResponse.json(
    99→      { error: 'Internal server error' },
   100→      { status: 500 }
   101→    );
   102→  }
   103→}
   104→
   105→/**
   106→ * GET /api/ideas
   107→ *
   108→ * List ideas from the queue. This is a protected endpoint.
   109→ * Requires X-ORCH-KEY header for authentication.
   110→ *
   111→ * Query parameters:
   112→ * - status: Comma-separated statuses (default: "submitted,ready")
   113→ * - limit: Max results (default: 50, max: 100)
   114→ * - offset: Pagination offset (default: 0)
   115→ * - sort: Sort field (default: "createdAt")
   116→ * - order: Sort order "asc" or "desc" (default: "asc")
   117→ *
   118→ * Response:
   119→ * - 200 OK: { ideas, total, limit, offset }
   120→ * - 400 Bad Request: { error, message, validStatuses? }
   121→ * - 401 Unauthorized: { error, message }
   122→ * - 500 Internal Server Error: { error, message }
   123→ */
   124→export async function GET(request: NextRequest) {
   125→  const startTime = performance.now();
   126→
   127→  try {
   128→    // 1. Authentication - require X-ORCH-KEY header
   129→    if (!validateOrchKey(request)) {
   130→      console.warn('[API] GET /api/ideas: Authentication failed');
   131→      return NextResponse.json(
   132→        {
   133→          error: 'UNAUTHORIZED',
   134→          message: 'Invalid or missing X-ORCH-KEY header',
   135→        },
   136→        { status: 401 }
   137→      );
   138→    }
   139→
   140→    // 2. Parse and validate query parameters
   141→    const searchParams = request.nextUrl.searchParams;
   142→    let params;
   143→    try {
   144→      params = validateListIdeasParams(searchParams);
   145→    } catch (error) {
   146→      if (error instanceof ValidationError) {
   147→        console.warn('[API] GET /api/ideas: Validation error:', error.message);
   148→        return NextResponse.json(
   149→          {
   150→            error: 'VALIDATION_ERROR',
