     1→import { z } from 'zod';
     2→
     3→/**
     4→ * Configuration for the Intake Sync service
     5→ */
     6→export interface IntakeSyncConfig {
     7→  /** Whether sync is enabled */
     8→  enabled: boolean;
     9→  /** Intake API base URL */
    10→  intakeBaseUrl: string;
    11→  /** Orchestrator API key for authentication */
    12→  orchKey: string;
    13→  /** Request timeout in milliseconds */
    14→  requestTimeout: number;
    15→  /** Throttle interval in milliseconds (min time between updates for same project) */
    16→  throttleInterval: number;
    17→  /** Maximum retry attempts for transient errors */
    18→  maxRetries: number;
    19→  /** Maximum queue size */
    20→  maxQueueSize: number;
    21→  /** Retry delay in milliseconds (base for exponential backoff) */
    22→  retryDelay: number;
    23→}
    24→
    25→/**
    26→ * Default configuration values
    27→ */
    28→export const DEFAULT_INTAKE_SYNC_CONFIG: Partial<IntakeSyncConfig> = {
    29→  enabled: true,
    30→  requestTimeout: 10_000,
    31→  throttleInterval: 5_000,
    32→  maxRetries: 3,
    33→  maxQueueSize: 50,
    34→  retryDelay: 1_000,
    35→};
    36→
    37→/**
    38→ * Environment variable schema for Intake Sync configuration
    39→ */
    40→const envSchema = z.object({
    41→  SYNC_ENABLED: z
    42→    .enum(['true', 'false'])
    43→    .transform((v) => v === 'true')
    44→    .default('true'),
    45→  INTAKE_API_BASE_URL: z.string().url(),
    46→  ORCH_KEY: z.string().min(16, 'ORCH_KEY must be at least 16 characters'),
    47→  SYNC_REQUEST_TIMEOUT: z.coerce.number().int().positive().optional(),
    48→  SYNC_THROTTLE_INTERVAL: z.coerce.number().int().positive().optional(),
    49→  SYNC_MAX_RETRIES: z.coerce.number().int().min(0).max(10).optional(),
    50→  SYNC_MAX_QUEUE_SIZE: z.coerce.number().int().positive().max(1000).optional(),
    51→  SYNC_RETRY_DELAY: z.coerce.number().int().positive().optional(),
    52→});
    53→
    54→/**
    55→ * Load and validate configuration from environment variables
    56→ * @throws Error if required variables are missing or invalid
    57→ */
    58→export function loadIntakeSyncConfig(): IntakeSyncConfig {
    59→  const result = envSchema.safeParse(process.env);
    60→
    61→  if (!result.success) {
    62→    const errors = result.error.errors
    63→      .map((e) => `  ${e.path.join('.')}: ${e.message}`)
    64→      .join('\n');
    65→    throw new Error(`Intake Sync configuration validation failed:\n${errors}`);
    66→  }
    67→
    68→  const env = result.data;
    69→
    70→  return {
    71→    enabled: env.SYNC_ENABLED,
    72→    intakeBaseUrl: env.INTAKE_API_BASE_URL,
    73→    orchKey: env.ORCH_KEY,
    74→    requestTimeout: env.SYNC_REQUEST_TIMEOUT ?? DEFAULT_INTAKE_SYNC_CONFIG.requestTimeout!,
    75→    throttleInterval: env.SYNC_THROTTLE_INTERVAL ?? DEFAULT_INTAKE_SYNC_CONFIG.throttleInterval!,
    76→    maxRetries: env.SYNC_MAX_RETRIES ?? DEFAULT_INTAKE_SYNC_CONFIG.maxRetries!,
    77→    maxQueueSize: env.SYNC_MAX_QUEUE_SIZE ?? DEFAULT_INTAKE_SYNC_CONFIG.maxQueueSize!,
    78→    retryDelay: env.SYNC_RETRY_DELAY ?? DEFAULT_INTAKE_SYNC_CONFIG.retryDelay!,
    79→  };
    80→}
    81→
    82→/**
    83→ * Validate configuration values
    84→ * @throws Error if configuration is invalid
    85→ */
    86→export function validateIntakeSyncConfig(config: IntakeSyncConfig): void {
    87→  if (!config.intakeBaseUrl.startsWith('http://') && !config.intakeBaseUrl.startsWith('https://')) {
    88→    throw new Error('Invalid INTAKE_API_BASE_URL: must be a valid URL');
    89→  }
    90→
    91→  if (config.orchKey.length < 16) {
    92→    throw new Error('Invalid ORCH_KEY: must be at least 16 characters');
    93→  }
    94→
    95→  if (config.requestTimeout <= 0) {
    96→    throw new Error('Invalid SYNC_REQUEST_TIMEOUT: must be positive');
    97→  }
    98→
    99→  if (config.throttleInterval < 0) {
   100→    throw new Error('Invalid SYNC_THROTTLE_INTERVAL: must be non-negative');
   101→  }
   102→
   103→  if (config.maxRetries < 0 || config.maxRetries > 10) {
   104→    throw new Error('Invalid SYNC_MAX_RETRIES: must be between 0 and 10');
   105→  }
   106→
   107→  if (config.maxQueueSize <= 0 || config.maxQueueSize > 1000) {
   108→    throw new Error('Invalid SYNC_MAX_QUEUE_SIZE: must be between 1 and 1000');
   109→  }
   110→
   111→  if (config.retryDelay <= 0) {
   112→    throw new Error('Invalid SYNC_RETRY_DELAY: must be positive');
   113→  }
   114→}
   115→
   116→/**
   117→ * Get a redacted version of config for logging (no secrets)
   118→ */
   119→export function getRedactedIntakeSyncConfig(config: IntakeSyncConfig): Record<string, unknown> {
   120→  return {
   121→    enabled: config.enabled,
   122→    intakeBaseUrl: config.intakeBaseUrl,
   123→    orchKey: '[REDACTED]',
   124→    requestTimeout: config.requestTimeout,
   125→    throttleInterval: config.throttleInterval,
   126→    maxRetries: config.maxRetries,
   127→    maxQueueSize: config.maxQueueSize,
   128→    retryDelay: config.retryDelay,
   129→  };
   130→}
