     1→import type { IntakeSyncConfig } from './config.js';
     2→import type { ProjectState, IntakeStatusUpdatePayload } from './types.js';
     3→import { mapProjectStatusToIdeaStatus } from './types.js';
     4→import { createLogger } from '../../utils/logger.js';
     5→
     6→const logger = createLogger('IntakeSyncHttpClient');
     7→
     8→/**
     9→ * HTTP error with status code
    10→ */
    11→export class HttpError extends Error {
    12→  constructor(
    13→    message: string,
    14→    public readonly status: number,
    15→    public readonly body?: unknown
    16→  ) {
    17→    super(message);
    18→    this.name = 'HttpError';
    19→  }
    20→}
    21→
    22→/**
    23→ * HTTP client for Intake API status updates
    24→ */
    25→export class IntakeSyncHttpClient {
    26→  private readonly baseUrl: string;
    27→  private readonly apiKey: string;
    28→  private readonly timeout: number;
    29→  private readonly maxRetries: number;
    30→  private readonly retryDelay: number;
    31→
    32→  constructor(config: IntakeSyncConfig) {
    33→    this.baseUrl = config.intakeBaseUrl.replace(/\/$/, '');
    34→    this.apiKey = config.orchKey;
    35→    this.timeout = config.requestTimeout;
    36→    this.maxRetries = config.maxRetries;
    37→    this.retryDelay = config.retryDelay;
    38→  }
    39→
    40→  /**
    41→   * Send status update to Intake API
    42→   * @param ideaId - ID of the idea to update
    43→   * @param state - Current project state
    44→   * @returns Promise that resolves on success
    45→   */
    46→  async updateStatus(ideaId: string, state: ProjectState): Promise<void> {
    47→    const url = `${this.baseUrl}/api/ideas/${ideaId}/update`;
    48→    const payload = this.buildPayload(state);
    49→
    50→    logger.debug({ ideaId, status: payload.status }, 'Sending status update');
    51→
    52→    let lastError: Error | undefined;
    53→
    54→    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
    55→      try {
    56→        const response = await fetch(url, {
    57→          method: 'PATCH',
    58→          headers: {
    59→            'Content-Type': 'application/json',
    60→            Accept: 'application/json',
    61→            'X-ORCH-KEY': this.apiKey,
    62→          },
    63→          body: JSON.stringify(payload),
    64→          signal: AbortSignal.timeout(this.timeout),
    65→        });
    66→
    67→        if (response.ok) {
    68→          logger.info({ ideaId, status: payload.status }, 'Status update successful');
    69→          return;
    70→        }
    71→
    72→        const status = response.status;
    73→        let body: unknown;
    74→
    75→        try {
    76→          body = await response.json();
    77→        } catch {
    78→          body = { error: response.statusText };
    79→        }
    80→
    81→        const error = new HttpError(
    82→          `HTTP ${status}: ${response.statusText}`,
    83→          status,
    84→          body
    85→        );
    86→
    87→        // Don't retry on 4xx errors
    88→        if (status >= 400 && status < 500) {
    89→          throw error;
    90→        }
    91→
    92→        lastError = error;
    93→
    94→        // Retry on 5xx errors
    95→        if (attempt < this.maxRetries) {
    96→          const delay = this.retryDelay * Math.pow(2, attempt);
    97→          logger.warn(
    98→            { ideaId, status, attempt: attempt + 1, retryInMs: delay },
    99→            'Retrying status update'
   100→          );
   101→          await this.sleep(delay);
   102→        }
   103→      } catch (error) {
   104→        if (error instanceof HttpError) {
   105→          throw error;
   106→        }
   107→
   108→        // Network error - retry if possible
   109→        lastError = error instanceof Error ? error : new Error(String(error));
   110→
   111→        if (attempt < this.maxRetries) {
   112→          const delay = this.retryDelay * Math.pow(2, attempt);
   113→          logger.warn(
   114→            { ideaId, error: lastError.message, attempt: attempt + 1, retryInMs: delay },
   115→            'Retrying after network error'
   116→          );
   117→          await this.sleep(delay);
   118→        }
   119→      }
   120→    }
   121→
   122→    // All retries exhausted
   123→    logger.error({ ideaId, error: lastError?.message }, 'Status update failed after retries');
   124→    throw lastError ?? new Error('Unknown error');
   125→  }
   126→
   127→  /**
   128→   * Build the payload for Intake API
   129→   */
   130→  private buildPayload(state: ProjectState): IntakeStatusUpdatePayload {
   131→    const payload: IntakeStatusUpdatePayload = {
   132→      status: mapProjectStatusToIdeaStatus(state.status),
   133→    };
   134→
   135→    // Only include non-null optional fields
   136→    if (state.progress !== undefined && state.progress !== null) {
   137→      payload.progress = state.progress;
   138→    }
   139→
   140→    if (state.currentStep) {
   141→      payload.currentStep = state.currentStep;
   142→    }
   143→
   144→    if (state.currentFeature !== null) {
   145→      payload.currentFeature = state.currentFeature;
   146→    }
   147→
   148→    if (state.waitingQuestion !== null) {
   149→      payload.waitingQuestion = state.waitingQuestion;
   150→    }
   151→
   152→    if (state.demoUrl !== null) {
   153→      payload.demoUrl = state.demoUrl;
   154→    }
   155→
   156→    if (state.repoUrl !== null) {
   157→      payload.repoUrl = state.repoUrl;
   158→    }
   159→
   160→    return payload;
   161→  }
   162→
   163→  /**
   164→   * Sleep helper for retry delays
   165→   */
   166→  private sleep(ms: number): Promise<void> {
   167→    return new Promise((resolve) => setTimeout(resolve, ms));
   168→  }
   169→}
