     1→/**
     2→ * Validates the X-ORCH-KEY header for protected API endpoints
     3→ *
     4→ * This middleware is used by:
     5→ * - F3: Orchestrator Claim API
     6→ * - F4: Orchestrator Status Update API
     7→ * - F5: Ideas Queue API
     8→ *
     9→ * Security notes:
    10→ * - Uses constant-time comparison to prevent timing attacks
    11→ * - Never logs the actual secret value
    12→ * - Returns boolean (true = valid, false = invalid)
    13→ */
    14→
    15→/**
    16→ * Validate the X-ORCH-KEY header against the ORCH_KEY environment variable
    17→ *
    18→ * @param request - The incoming request (must have headers)
    19→ * @returns true if the header matches the environment variable, false otherwise
    20→ *
    21→ * @example
    22→ * ```typescript
    23→ * if (!validateOrchKey(request)) {
    24→ *   return Response.json({ error: 'Unauthorized' }, { status: 401 });
    25→ * }
    26→ * ```
    27→ */
    28→export function validateOrchKey(request: Request): boolean {
    29→  const headerKey = request.headers.get('X-ORCH-KEY');
    30→  const envKey = process.env.ORCH_KEY;
    31→
    32→  // Fail if either key is missing
    33→  if (!headerKey || !envKey) {
    34→    return false;
    35→  }
    36→
    37→  // Constant-time comparison to prevent timing attacks
    38→  if (headerKey.length !== envKey.length) {
    39→    return false;
    40→  }
    41→
    42→  let result = 0;
    43→  for (let i = 0; i < headerKey.length; i++) {
    44→    result |= headerKey.charCodeAt(i) ^ envKey.charCodeAt(i);
    45→  }
    46→
    47→  return result === 0;
    48→}
