    14→
    15→/**
    16→ * POST /api/ideas/[id]/claim
    17→ *
    18→ * Atomically claim an idea for processing. Protected endpoint.
    19→ *
    20→ * Headers:
    21→ * - X-ORCH-KEY: Shared secret for orchestrator authentication (required)
    22→ *
    23→ * URL Parameters:
    24→ * - id: UUID of the idea to claim
    25→ *
    26→ * Request Body (optional):
    27→ * - claimedBy: Identifier for who is claiming (e.g., orchestrator instance ID)
    28→ *
    29→ * Response:
    30→ * - 200 OK: Idea successfully claimed, returns full idea object
    31→ * - 400 Bad Request: Invalid UUID or request body
    32→ * - 401 Unauthorized: Invalid or missing X-ORCH-KEY
    33→ * - 404 Not Found: Idea with given ID does not exist
    34→ * - 409 Conflict: Idea is not claimable (already claimed, running, etc.)
    35→ * - 500 Internal Server Error: Unexpected error
    36→ */
    37→export async function POST(
    38→  request: NextRequest,
    39→  { params }: { params: Promise<{ id: string }> }
    40→): Promise<NextResponse> {
    41→  const startTime = performance.now();
    42→  const resolvedParams = await params;
    43→  const ideaId = resolvedParams.id;
    44→
    45→  try {
    46→    // 1. Authentication - require X-ORCH-KEY header
    47→    if (!validateOrchKey(request)) {
    48→      console.warn('[API] POST /api/ideas/[id]/claim: Authentication failed', { ideaId });
    49→      return formatAuthError();
    50→    }
    51→
    52→    // 2. Parse request body (may be empty)
    53→    let body: unknown;
    54→    try {
    55→      const text = await request.text();
    56→      body = text ? JSON.parse(text) : undefined;
    57→    } catch {
    58→      console.warn('[API] POST /api/ideas/[id]/claim: Invalid JSON body', { ideaId });
    59→      return formatValidationError([
    60→        { field: 'body', message: 'Request body must be valid JSON' }
    61→      ]);
    62→    }
    63→
    64→    // 3. Validate request (UUID + body)
    65→    let validated;
    66→    try {
    67→      validated = validateClaimRequest(ideaId, body);
    68→    } catch (error) {
    69→      if (error instanceof ValidationError) {
    70→        console.warn('[API] POST /api/ideas/[id]/claim: Validation failed', {
    71→          ideaId,
    72→          details: error.details,
    73→        });
    74→        return formatValidationError(error.details);
    75→      }
    76→      throw error;
    77→    }
    78→
    79→    // 4. Execute claim operation
    80→    const result = await claimIdea(validated.ideaId, validated.claimedBy);
    81→
    82→    // 5. Handle result
    83→    if (result.success) {
    84→      const durationMs = performance.now() - startTime;
    85→      console.log('[API] POST /api/ideas/[id]/claim: Success', {
    86→        ideaId: result.idea.id,
    87→        claimedBy: validated.claimedBy ?? '(anonymous)',
    88→        durationMs: Math.round(durationMs),
    89→      });
    90→      return formatSuccessResponse(result.idea);
    91→    }
    92→
    93→    // 6. Handle specific errors
    94→    if (result.error instanceof NotFoundError) {
    95→      console.log('[API] POST /api/ideas/[id]/claim: Not found', { ideaId });
    96→      return formatNotFoundError(ideaId);
    97→    }
    98→
    99→    if (result.error instanceof ConflictError) {
   100→      console.log('[API] POST /api/ideas/[id]/claim: Conflict', {
   101→        ideaId,
   102→        currentStatus: result.error.currentStatus,
   103→        claimedAt: result.error.claimedAt.toISOString(),
   104→        claimedBy: result.error.claimedBy,
   105→      });
   106→      return formatConflictResponse(
   107→        result.error.claimedAt,
   108→        result.error.claimedBy,
   109→        result.error.currentStatus
   110→      );
   111→    }
   112→
   113→    // Unexpected error type
   114→    console.error('[API] POST /api/ideas/[id]/claim: Unexpected error type', {
   115→      ideaId,
   116→      error: result.error,
   117→    });
   118→    return formatInternalError();
   119→
   120→  } catch (error) {
   121→    // Log full error details server-side
   122→    console.error('[API] POST /api/ideas/[id]/claim: Internal error', {
   123→      ideaId,
   124→      error: error instanceof Error ? error.message : 'Unknown error',
   125→      stack: error instanceof Error ? error.stack : undefined,
   126→    });
   127→
   128→    // Return safe error message to client
   129→    return formatInternalError();
   130→  }
   131→}
