    18→ *
    19→ * URL Parameters:
    20→ * - id: UUID of the idea to delete
    21→ *
    22→ * Response:
    23→ * - 200 OK: Idea successfully deleted
    24→ * - 400 Bad Request: Invalid UUID format
    25→ * - 401 Unauthorized: Invalid or missing X-ORCH-KEY
    26→ * - 404 Not Found: Idea with given ID does not exist
    27→ * - 500 Internal Server Error: Unexpected error
    28→ */
    29→export async function DELETE(
    30→  request: NextRequest,
    31→  { params }: { params: Promise<{ id: string }> }
    32→): Promise<NextResponse> {
    33→  const startTime = performance.now();
    34→  const resolvedParams = await params;
    35→  const ideaId = resolvedParams.id;
    36→
    37→  try {
    38→    // 1. Authentication - require X-ORCH-KEY header
