    50→    // 2. Validate UUID format
    51→    const uuidResult = UUIDSchema.safeParse(ideaId);
    52→    if (!uuidResult.success) {
    53→      console.warn('[API] DELETE /api/ideas/[id]: Invalid UUID', { ideaId });
    54→      return NextResponse.json(
    55→        {
    56→          error: 'VALIDATION_ERROR',
