    37→ * - Queues updates during throttle or errors
    38→ * - Retries transient errors
    39→ * - Emits events for monitoring
    40→ */
    41→export class IntakeSyncService extends EventEmitter {
    42→  private readonly config: IntakeSyncConfig;
    43→  private readonly stateChangeHandler: StateChangeHandler;
    44→  private readonly throttleManager: ThrottleManager;
    45→  private readonly updateQueue: UpdateQueue;
    46→  private readonly httpClient: IntakeSyncHttpClient;
    47→  private readonly idempotencyChecker: IdempotencyChecker;
    48→  private readonly errorHandler: ErrorHandler;
    49→
    50→  private metrics: SyncMetrics;
    51→  private isRunning: boolean = false;
    52→  private activeOperations: number = 0;
    53→
    54→  /**
    55→   * Create a new IntakeSyncService
    56→   * @param config - Service configuration
    57→   * @param stateEmitter - Event emitter that emits 'state-changed' events
    58→   */
    59→  constructor(config: IntakeSyncConfig, stateEmitter: StateEmitter) {
    60→    super();
    61→
    62→    this.config = config;
    63→
    64→    // Initialize components
    65→    this.stateChangeHandler = new StateChangeHandler(stateEmitter);
    66→    this.throttleManager = new ThrottleManager();
    67→    this.updateQueue = new UpdateQueue(config.maxQueueSize);
    68→    this.httpClient = new IntakeSyncHttpClient(config);
    69→    this.idempotencyChecker = new IdempotencyChecker();
    70→    this.errorHandler = new ErrorHandler();
    71→
    72→    // Initialize metrics
    73→    this.metrics = this.createInitialMetrics();
    74→  }
    75→
    76→  /**
    77→   * Start the sync service
    78→   * Begins listening for state change events
    79→   */
    80→  start(): void {
    81→    if (this.isRunning) {
    82→      logger.warn('Sync service already running');
    83→      return;
    84→    }
    85→
    86→    if (!this.config.enabled) {
    87→      logger.info('Sync service is disabled by configuration');
    88→      return;
    89→    }
    90→
    91→    logger.info({ config: this.getRedactedConfig() }, 'Starting Intake sync service');
    92→
    93→    this.stateChangeHandler.subscribe((event) => this.handleStateChange(event));
    94→    this.isRunning = true;
    95→
    96→    this.emit('started');
    97→    logger.info('Intake sync service started');
    98→  }
    99→
