    41→ * @param queueService - Queue service instance
    42→ * @param intakeClient - Optional Intake client for delete operations
    43→ * @returns Express router with queue routes
    44→ */
    45→export function createQueueRoutes(
    46→  queueService: IQueueService,
    47→  intakeClient?: IIntakeClient
    48→): Router {
    49→  const router = Router();
    50→
    51→  /**
    52→   * GET /api/queue
    53→   * Fetch ideas from the queue (cached)
    54→   *
    55→   * Response Headers:
    56→   * - X-Cache-Age: Age of the cache in seconds
    57→   * - X-Cache-Status: hit | miss | stale
    58→   *
    59→   * Response Body: QueueResponse
    60→   */
    61→  router.get('/queue', async (_req: Request, res: Response<QueueResponse | ErrorResponse>) => {
    62→    const startTime = Date.now();
    63→
    64→    try {
    65→      logger.debug('GET /api/queue request received');
    66→
    67→      const result = await queueService.getQueue();
    68→      const cacheStatus = queueService.getCacheStatus();
    69→
    70→      // Calculate cache age in seconds
    71→      const cacheAge = cacheStatus.lastFetch
    72→        ? Math.floor((Date.now() - new Date(cacheStatus.lastFetch).getTime()) / 1000)
    73→        : 0;
    74→
    75→      // Determine cache status label
    76→      let statusLabel: string;
    77→      if (!cacheStatus.hasData) {
    78→        statusLabel = 'miss';
    79→      } else if (cacheStatus.isStale) {
    80→        statusLabel = 'stale';
    81→      } else {
    82→        statusLabel = 'hit';
    83→      }
    84→
    85→      // Set cache headers
    86→      res.set('X-Cache-Age', cacheAge.toString());
    87→      res.set('X-Cache-Status', statusLabel);
    88→
    89→      const duration = Date.now() - startTime;
    90→      logger.info(
    91→        { count: result.total, cacheStatus: statusLabel, durationMs: duration },
    92→        'GET /api/queue response'
    93→      );
    94→
    95→      res.json({
    96→        ideas: result.ideas,
    97→        total: result.total,
    98→        fetchedAt: result.fetchedAt,
    99→        fromCache: result.fromCache,
   100→      });

