import * as schema from './schema';

/**
 * Drizzle ORM client configured for PostgreSQL
 *
 * Automatically selects the appropriate database client:
 * - Local development: Uses standard `postgres` client
 * - Production (Vercel): Uses `@vercel/postgres` for optimized serverless connections
 * 
 * Uses the POSTGRES_URL environment variable.
 * 
 * Detection logic:
 * - Checks for VERCEL=1 environment variable (set automatically by Vercel)
 * - Defaults to local postgres client for development
 */

const connectionString = process.env.POSTGRES_URL;

if (!connectionString) {
  throw new Error('POSTGRES_URL environment variable is required');
}

// Detect if we're running on Vercel (production)
// Vercel sets the VERCEL environment variable automatically
const isVercel = process.env.VERCEL === '1';

// Initialize clients based on environment
let db: ReturnType<typeof import('drizzle-orm/vercel-postgres').drizzle> | ReturnType<typeof import('drizzle-orm/postgres-js').drizzle>;
let sql: ReturnType<typeof import('@vercel/postgres').sql> | ReturnType<typeof import('postgres').default>;

if (isVercel) {
  // Production: Use Vercel Postgres (optimized for serverless)
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { drizzle: drizzleVercel } = require('drizzle-orm/vercel-postgres');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { sql: sqlVercel } = require('@vercel/postgres');

  sql = sqlVercel;
  db = drizzleVercel(sql, { schema });
} else {
  // Development: Use standard postgres client (works with local PostgreSQL)
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { drizzle: drizzlePostgres } = require('drizzle-orm/postgres-js');
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const postgres = require('postgres');

  // postgres is a default export, so when using require, it's the function itself
  const client = postgres(connectionString, {
    max: 1, // Limit connection pool for serverless-like behavior
  });

  sql = client;
  db = drizzlePostgres(client, { schema });
}

export { db, sql };

import { defineConfig } from 'drizzle-kit';

export default defineConfig({
  schema: './lib/db/schema.ts',
  out: './drizzle/migrations',
  dialect: 'postgresql',
  dbCredentials: {
    url: process.env.POSTGRES_URL!,
  },
  verbose: true,
  strict: true,
});

