import { Metadata } from 'next';
import SubmitForm from './SubmitForm';

/**
 * Page metadata for SEO and social sharing
 */
export const metadata: Metadata = {
  title: 'Submit Your Idea | UT messa POC Builder',
  description: 'Submit your POC idea and watch it get built in real-time at the UT messa conference booth',
  openGraph: {
    title: 'Submit Your POC Idea',
    description: 'Submit your POC idea and watch it get built in real-time',
    type: 'website',
  },
};

/**
 * Submit page - Main entry point for idea submission
 *
 * This is a server component that renders the page container.
 * The SubmitForm component is a client component that handles
 * form state and submission.
 *
 * Route: /submit
 */
export default function SubmitPage() {
  return (
    <main className="min-h-screen bg-gradient-to-b from-gray-50 to-gray-100 py-8 px-4 sm:py-12">
      <div className="max-w-2xl mx-auto">
        {/* Page Header */}
        <header className="text-center mb-8">
          <h1 className="text-3xl sm:text-4xl font-bold text-gray-900 mb-3">
            Submit Your POC Idea
          </h1>
          <p className="text-gray-600 text-lg">
            Tell us what you want built, and we&apos;ll create a working demo
          </p>
        </header>

        {/* Submission Form */}
        <SubmitForm />

        {/* Page Footer */}
        <footer className="mt-8 text-center text-sm text-gray-500">
          <p>Built for UT messa conference booth</p>
          <p className="mt-1">
            Powered by AI &mdash; Your idea, built in real-time
          </p>
        </footer>
      </div>
    </main>
  );
}

