'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { SubmitIdeaRequestSchema } from '@utmessa/shared';
import type { SubmitIdeaResponse } from '@utmessa/shared';
import FormField from './components/FormField';
import MustHavesList from './components/MustHavesList';
import SubmitButton from './components/SubmitButton';
import SuccessMessage from './components/SuccessMessage';

/**
 * Form data structure
 */
interface FormData {
  title: string;
  problem: string;
  mustHaves: string[];
  email: string;
}

/**
 * Main submission form component
 *
 * Features:
 * - Manages form state (title, problem, mustHaves, email)
 * - Client-side validation with Zod schemas from @utmessa/shared
 * - Submits to POST /api/ideas
 * - Handles loading states and errors
 * - Displays success message and redirects to receipt page
 *
 * @example
 * ```tsx
 * <SubmitForm />
 * ```
 */
export default function SubmitForm() {
  const router = useRouter();

  // Form state
  const [formData, setFormData] = useState<FormData>({
    title: '',
    problem: '',
    mustHaves: [''],
    email: '',
  });

  // Validation errors (keyed by field path)
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Submission state
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [receiptToken, setReceiptToken] = useState<string | null>(null);
  const [apiError, setApiError] = useState<string | null>(null);

  // Auto-redirect after successful submission
  useEffect(() => {
    if (submitSuccess && receiptToken) {
      const timer = setTimeout(() => {
        router.push(`/i/${receiptToken}`);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [submitSuccess, receiptToken, router]);

  /**
   * Validate the entire form and return whether it's valid
   */
  const validateForm = (): boolean => {
    // Prepare data for validation (trim strings, filter empty mustHaves)
    const dataToValidate = {
      title: formData.title.trim(),
      problem: formData.problem.trim(),
      mustHaves: formData.mustHaves
        .map((h) => h.trim())
        .filter((h) => h.length > 0),
      email: formData.email.trim() || undefined,
    };

    // Validate with Zod schema
    const result = SubmitIdeaRequestSchema.safeParse(dataToValidate);

    if (!result.success) {
      const newErrors: Record<string, string> = {};
      result.error.errors.forEach((err) => {
        const path = err.path.join('.');
        newErrors[path] = err.message;
      });
      setErrors(newErrors);
      return false;
    }

    setErrors({});
    return true;
  };

  /**
   * Handle form submission
   */
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate form
    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);
    setApiError(null);

    try {
      // Prepare request data
      const requestData = {
        title: formData.title.trim(),
        problem: formData.problem.trim(),
        mustHaves: formData.mustHaves
          .map((h) => h.trim())
          .filter((h) => h.length > 0),
        email: formData.email.trim() || undefined,
      };

      // Submit to API
      const response = await fetch('/api/ideas', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestData),
      });

      // Handle response
      if (!response.ok) {
        if (response.status === 400) {
          const errorData = await response.json();
          setApiError(errorData.error || 'Validation failed. Please check your input.');
        } else if (response.status >= 500) {
          setApiError('Server error. Please try again later.');
        } else {
          setApiError('An unexpected error occurred. Please try again.');
        }
        return;
      }

      // Success
      const data: SubmitIdeaResponse = await response.json();
      setReceiptToken(data.token);
      setSubmitSuccess(true);
    } catch (error) {
      console.error('Submission error:', error);
      setApiError('Network error. Please check your connection and try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  // Show success message after submission
  if (submitSuccess && receiptToken) {
    return <SuccessMessage token={receiptToken} />;
  }

  return (
    <form
      onSubmit={handleSubmit}
      className="bg-white rounded-lg shadow-lg p-6 space-y-6"
      noValidate
    >
      {/* Privacy Notice */}
      <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded-r">
        <p className="text-sm text-yellow-800">
          <strong>Privacy Notice:</strong> Do not include sensitive, confidential,
          or personal information. This is a public demo system.
        </p>
      </div>

      {/* Title Field */}
      <FormField
        label="Idea Title"
        name="title"
        required
        maxLength={100}
        value={formData.title}
        onChange={(value) => setFormData({ ...formData, title: value })}
        error={errors.title}
        placeholder="e.g., Recipe sharing app for families"
        autoFocus
      />

      {/* Problem Field */}
      <FormField
        label="Problem Description"
        name="problem"
        type="textarea"
        required
        maxLength={500}
        minLength={10}
        value={formData.problem}
        onChange={(value) => setFormData({ ...formData, problem: value })}
        error={errors.problem}
        placeholder="Describe the problem you want to solve..."
        rows={4}
      />

      {/* Must-Haves List */}
      <MustHavesList
        items={formData.mustHaves}
        onChange={(items) => setFormData({ ...formData, mustHaves: items })}
        errors={errors}
      />

      {/* Email Field */}
      <FormField
        label="Email (optional)"
        name="email"
        type="email"
        value={formData.email}
        onChange={(value) => setFormData({ ...formData, email: value })}
        error={errors.email}
        placeholder="your.email@example.com"
        helpText="Receive notifications when your POC is ready"
      />

      {/* API Error */}
      {apiError && (
        <div className="bg-red-50 border-l-4 border-red-400 p-4 rounded-r" role="alert">
          <p className="text-sm text-red-800">{apiError}</p>
        </div>
      )}

      {/* Submit Button */}
      <SubmitButton isSubmitting={isSubmitting} />
    </form>
  );
}

'use client';

import CharacterCounter from './CharacterCounter';

interface FormFieldProps {
  /** Field label text */
  label: string;
  /** Field name for form handling */
  name: string;
  /** Input type: text, email, or textarea */
  type?: 'text' | 'email' | 'textarea';
  /** Whether the field is required */
  required?: boolean;
  /** Maximum character length */
  maxLength?: number;
  /** Minimum character length */
  minLength?: number;
  /** Current value */
  value: string;
  /** Change handler */
  onChange: (value: string) => void;
  /** Error message to display */
  error?: string;
  /** Placeholder text */
  placeholder?: string;
  /** Help text displayed below the field */
  helpText?: string;
  /** Number of rows for textarea */
  rows?: number;
  /** Whether to auto-focus this field */
  autoFocus?: boolean;
}

/**
 * Reusable form field component with label, validation, and character counter
 *
 * Features:
 * - Renders input or textarea based on type
 * - Displays required indicator (*) when required
 * - Shows character counter when maxLength is provided
 * - Displays error messages with proper ARIA attributes
 * - Help text for guidance
 *
 * @example
 * ```tsx
 * <FormField
 *   label="Idea Title"
 *   name="title"
 *   required
 *   maxLength={100}
 *   value={title}
 *   onChange={setTitle}
 *   error={errors.title}
 *   placeholder="e.g., Recipe sharing app"
 * />
 * ```
 */
export default function FormField({
  label,
  name,
  type = 'text',
  required = false,
  maxLength,
  minLength,
  value,
  onChange,
  error,
  placeholder,
  helpText,
  rows = 3,
  autoFocus = false,
}: FormFieldProps) {
  const inputClassName = `
    w-full px-4 py-3 border rounded-lg
    focus:outline-none focus:ring-2 focus:ring-blue-500
    transition-colors duration-200
    ${error ? 'border-red-500 bg-red-50' : 'border-gray-300 bg-white'}
  `;

  const commonProps = {
    id: name,
    name,
    value,
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>
      onChange(e.target.value),
    placeholder,
    maxLength,
    minLength,
    required,
    autoFocus,
    className: inputClassName,
    'aria-invalid': !!error,
    'aria-describedby': error ? `${name}-error` : helpText ? `${name}-help` : undefined,
  };

  return (
    <div className="space-y-1">
      <label
        htmlFor={name}
        className="block text-sm font-medium text-gray-700"
      >
        {label}
        {required && (
          <span className="text-red-500 ml-1" aria-label="required">
            *
          </span>
        )}
      </label>

      {type === 'textarea' ? (
        <textarea {...commonProps} rows={rows} />
      ) : (
        <input type={type} {...commonProps} />
      )}

      {/* Character Counter */}
      {maxLength && <CharacterCounter current={value.length} max={maxLength} />}

      {/* Help Text */}
      {helpText && !error && (
        <p id={`${name}-help`} className="text-sm text-gray-500">
          {helpText}
        </p>
      )}

      {/* Error Message */}
      {error && (
        <p
          id={`${name}-error`}
          className="text-sm text-red-600"
          role="alert"
        >
          {error}
        </p>
      )}
    </div>
  );
}

