'use client';

interface MustHavesListProps {
  /** Array of must-have feature strings */
  items: string[];
  /** Handler for when items change */
  onChange: (items: string[]) => void;
  /** Error messages keyed by field path (e.g., "mustHaves.0") */
  errors: Record<string, string>;
}

/** Maximum number of must-have features allowed */
const MAX_ITEMS = 10;
/** Minimum number of must-have features required */
const MIN_ITEMS = 1;
/** Maximum length per feature */
const MAX_LENGTH = 100;

/**
 * Dynamic list component for must-have features
 *
 * Features:
 * - Renders list of input fields
 * - Add button to add new items (max 10)
 * - Remove button to delete items (min 1)
 * - Individual character limits per item
 * - ARIA labels for accessibility
 *
 * @example
 * ```tsx
 * <MustHavesList
 *   items={['Feature 1', 'Feature 2']}
 *   onChange={setMustHaves}
 *   errors={{ 'mustHaves.0': 'Required' }}
 * />
 * ```
 */
export default function MustHavesList({
  items,
  onChange,
  errors,
}: MustHavesListProps) {
  const addItem = () => {
    if (items.length < MAX_ITEMS) {
      onChange([...items, '']);
    }
  };

  const removeItem = (index: number) => {
    if (items.length > MIN_ITEMS) {
      onChange(items.filter((_, i) => i !== index));
    }
  };

  const updateItem = (index: number, value: string) => {
    const newItems = [...items];
    newItems[index] = value;
    onChange(newItems);
  };

  return (
    <div className="space-y-3">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          Must-Have Features{' '}
          <span className="text-red-500" aria-label="required">
            *
          </span>
        </label>
        <p className="text-sm text-gray-600 mb-3">
          List 1-10 key features your POC must have
        </p>
      </div>

      <div className="space-y-3">
        {items.map((item, index) => (
          <div key={index} className="flex gap-2">
            <div className="flex-1">
              <input
                type="text"
                value={item}
                onChange={(e) => updateItem(index, e.target.value)}
                placeholder={`Feature ${index + 1}`}
                maxLength={MAX_LENGTH}
                className={`
                  w-full px-4 py-3 border rounded-lg
                  focus:outline-none focus:ring-2 focus:ring-blue-500
                  transition-colors duration-200
                  ${errors[`mustHaves.${index}`] ? 'border-red-500 bg-red-50' : 'border-gray-300 bg-white'}
                `}
                aria-label={`Must-have feature ${index + 1}`}
                aria-invalid={!!errors[`mustHaves.${index}`]}
              />
              {errors[`mustHaves.${index}`] && (
                <p className="mt-1 text-sm text-red-600" role="alert">
                  {errors[`mustHaves.${index}`]}
                </p>
              )}
            </div>

            {items.length > MIN_ITEMS && (
              <button
                type="button"
                onClick={() => removeItem(index)}
                className="px-4 py-3 text-red-600 hover:bg-red-50 rounded-lg transition-colors duration-200 font-medium"
                aria-label={`Remove feature ${index + 1}`}
              >
                Remove
              </button>
            )}
          </div>
        ))}
      </div>

      {items.length < MAX_ITEMS && (
        <button
          type="button"
          onClick={addItem}
          className="px-4 py-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors duration-200 border border-blue-600 font-medium"
        >
          + Add Feature
        </button>
      )}

      {/* General array-level error (e.g., "At least one feature required") */}
      {errors.mustHaves && (
        <p className="text-sm text-red-600" role="alert">
          {errors.mustHaves}
        </p>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';

interface SuccessMessageProps {
  /** The receipt token for the submitted idea */
  token: string;
}

/**
 * Success message component displayed after successful submission
 *
 * Features:
 * - Success icon and congratulatory message
 * - Displays the receipt URL
 * - Copy button with visual feedback
 * - Auto-redirect countdown
 * - Manual navigation link
 *
 * @example
 * ```tsx
 * <SuccessMessage token="V1StGXR8Z5jdHi9B2vBJ4" />
 * ```
 */
export default function SuccessMessage({ token }: SuccessMessageProps) {
  const [copied, setCopied] = useState(false);
  const [countdown, setCountdown] = useState(3);

  // Build the receipt URL
  const receiptUrl =
    typeof window !== 'undefined'
      ? `${window.location.origin}/i/${token}`
      : `/i/${token}`;

  // Countdown timer
  useEffect(() => {
    const timer = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  // Copy to clipboard handler
  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(receiptUrl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // Fallback for older browsers
      const textArea = document.createElement('textarea');
      textArea.value = receiptUrl;
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="bg-white rounded-lg shadow-lg p-8 text-center">
      {/* Success Icon */}
      <div className="mx-auto w-16 h-16 bg-green-100 rounded-full flex items-center justify-center mb-6">
        <svg
          className="w-10 h-10 text-green-600"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
          aria-hidden="true"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="2"
            d="M5 13l4 4L19 7"
          />
        </svg>
      </div>

      {/* Success Message */}
      <h2 className="text-2xl font-bold text-gray-900 mb-2">
        Idea Submitted Successfully!
      </h2>
      <p className="text-gray-600 mb-6">
        Your POC is in the build queue. Use this link to track progress:
      </p>

      {/* Receipt URL */}
      <div className="bg-gray-50 rounded-lg p-4 mb-6">
        <p className="text-sm font-mono text-gray-700 break-all mb-3">
          {receiptUrl}
        </p>
        <button
          type="button"
          onClick={copyToClipboard}
          className={`
            px-6 py-2 rounded-lg font-medium transition-all duration-200
            focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2
            ${
              copied
                ? 'bg-green-600 text-white'
                : 'bg-blue-600 text-white hover:bg-blue-700'
            }
          `}
          aria-live="polite"
        >
          {copied ? (
            <span className="flex items-center justify-center gap-2">
              <svg
                className="w-4 h-4"
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
                aria-hidden="true"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M5 13l4 4L19 7"
                />
              </svg>
              Copied!
            </span>
          ) : (
            'Copy Link'
          )}
        </button>
      </div>

      {/* Redirect Notice */}
      <p className="text-sm text-gray-500 mb-6">
        Redirecting to your receipt page in {countdown} second{countdown !== 1 ? 's' : ''}...
      </p>

      {/* Manual Navigation */}
      <a
        href={`/i/${token}`}
        className="inline-block px-8 py-3 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 transition-colors duration-200 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2"
      >
        View Receipt Now
      </a>
    </div>
  );
}

