import { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { getIdeaByToken } from '@/lib/db';
import type { IdeaStatus } from '@utmessa/shared';
import {
  StatusBadge,
  ProgressDisplay,
  WaitingAlert,
  OutputLinks,
  IdeaDetailsCard,
} from '@/components/receipt';

interface PageProps {
  params: Promise<{ token: string }>;
}

/**
 * Generate dynamic metadata for SEO and social sharing
 * Pages are marked noindex to prevent search engine indexing
 */
export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const resolvedParams = await params;
  const idea = await getIdeaByToken(resolvedParams.token);

  if (!idea) {
    return {
      title: 'Receipt Not Found | UT messa POC Builder',
      robots: 'noindex, nofollow',
    };
  }

  return {
    title: `${idea.title} - Receipt | UT messa POC Builder`,
    description: idea.problem.slice(0, 160),
    robots: 'noindex, nofollow',
    openGraph: {
      title: idea.title,
      description: idea.problem.slice(0, 160),
    },
  };
}

/**
 * Receipt page - View submitted idea and build progress
 *
 * This server component fetches idea data and renders the receipt page.
 * Shows:
 * - Current build status with color-coded badge
 * - Build progress with percentage and current step
 * - Idea details (title, problem, must-haves)
 * - Alert when waiting for user input
 * - Links to demo and repository when deployed
 *
 * Route: /i/[token]
 */
export default async function ReceiptPage({ params }: PageProps) {
  const resolvedParams = await params;
  const idea = await getIdeaByToken(resolvedParams.token);

  if (!idea) {
    notFound();
  }

  const createdDate = new Date(idea.createdAt).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-3xl mx-auto">
        {/* Header */}
        <header className="mb-8 text-center">
          <h1 className="text-2xl sm:text-3xl font-bold text-gray-900">
            UT messa POC Builder
          </h1>
          <p className="text-sm text-gray-600 mt-2">
            Receipt for your submitted idea
          </p>
        </header>

        <main className="space-y-6">
          {/* Status and Progress Card */}
          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4">
              <div>
                <span className="text-sm text-gray-500">Status</span>
              </div>
              <StatusBadge status={idea.status as IdeaStatus} />
            </div>

            <ProgressDisplay
              progress={idea.progress ?? undefined}
              currentStep={idea.currentStep ?? undefined}
              currentFeature={idea.currentFeature ?? undefined}
            />
          </div>

          {/* Waiting Alert */}
          {idea.status === 'waiting' && idea.waitingQuestion && (
            <WaitingAlert question={idea.waitingQuestion} />
          )}

          {/* Output Links (Demo & Repo) */}
          <OutputLinks
            demoUrl={idea.demoUrl ?? undefined}
            repoUrl={idea.repoUrl ?? undefined}
          />

          {/* Idea Details */}
          <IdeaDetailsCard
            title={idea.title}
            problem={idea.problem}
            mustHaves={idea.mustHaves}
          />

          {/* Metadata Footer */}
          <div className="text-center text-sm text-gray-500 space-y-1">
            <p>Submitted on {createdDate}</p>
            <p className="text-xs text-gray-400 break-all">
              Receipt ID: {idea.token}
            </p>
          </div>
        </main>

        {/* Footer */}
        <footer className="mt-8 text-center text-sm text-gray-500">
          <p>Keep this link safe to track your POC build progress.</p>
          <p className="mt-2">
            <a
              href="/submit"
              className="text-blue-600 hover:text-blue-700 hover:underline"
            >
              Submit another idea
            </a>
          </p>
        </footer>
      </div>
    </div>
  );
}

'use client';

import { useEffect } from 'react';

interface ErrorProps {
  error: Error & { digest?: string };
  reset: () => void;
}

/**
 * Error boundary for receipt page
 *
 * Catches unexpected errors during rendering and provides a recovery UI.
 */
export default function Error({ error, reset }: ErrorProps) {
  useEffect(() => {
    // Log error to console for debugging (could send to error tracking service)
    console.error('[Receipt Page Error]', error);
  }, [error]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 py-8 px-4">
      <div className="text-center max-w-md">
        <div className="mx-auto w-16 h-16 bg-yellow-100 rounded-full flex items-center justify-center mb-6">
          <svg
            className="w-8 h-8 text-yellow-600"
            fill="none"
            viewBox="0 0 24 24"
            strokeWidth="1.5"
            stroke="currentColor"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M12 9v3.75m9-.75a9 9 0 11-18 0 9 9 0 0118 0zm-9 3.75h.008v.008H12v-.008z"
            />
          </svg>
        </div>

        <h2 className="text-2xl font-bold text-gray-900 mb-4">
          Something went wrong
        </h2>

        <p className="text-gray-600 mb-8">
          We encountered an error loading your receipt. This might be a temporary issue.
          Please try again.
        </p>

        <button
          onClick={reset}
